def lower(component, view, public, kernel):
    facts = []
    negatives = []
    witnesses = []
    reasons = []
    complete = True
    if type(view) is not dict or view.get('extraction_status') != 'complete':
        return part([], [], [], False, [component + '_unread_or_ambiguous'])
    if not support(witnesses, view, public, False):
        complete = False
        add(reasons, component + '_complete_view_requires_current_witness')
    institutions = view.get('institutions')
    enrollments = view.get('enrollments')
    attendance = view.get('attendance')
    if type(institutions) is not list or type(enrollments) is not list or type(attendance) is not list:
        return part(facts, negatives, witnesses, False, reasons + ['education_channels_unread'])
    for index, record in enumerate(institutions):
        if not support(witnesses, record, public, True) or type(record.get('institution')) is not str:
            complete = False
            continue
        event = 'educational_institution_' + str(index)
        put(facts, 'educational_institution_', [event])
        put(facts, 'agent_', [event, record.get('institution')])
    for channel, predicate, place in (('enrollments', 'enrollment_', 'patient_'), ('attendance', 'attending_classes_', 'location_')):
        rows = enrollments if channel == 'enrollments' else attendance
        for index, record in enumerate(rows):
            if not support(witnesses, record, public, True) or type(record.get('person')) is not str or type(record.get('institution')) is not str:
                complete = False
                continue
            event = channel + '_' + str(index)
            local = []
            if state_time(local, event, record, reasons, channel, False):
                put(facts, predicate, [event])
                put(facts, 'agent_', [event, record.get('person')])
                put(facts, place, [event, record.get('institution')])
                for row in local:
                    add(facts, row)
            else:
                complete = False
    if not complete:
        add(reasons, component + '_one_or_more_records_unread_or_invalid')
    return part(facts, negatives, witnesses, complete, reasons)

def apply(inputs, premises):
