def date_pattern():
    return r'(?:\d{4}-\d{2}-\d{2}|(?:January|February|March|April|May|June|July|August|September|October|November|December|Jan|Feb|Mar|Apr|Jun|Jul|Aug|Sep|Sept|Oct|Nov|Dec)\s+\d{1,2}(?:st|nd|rd|th)?(?:,)?\s+\d{4})'

def normalize_date(value):
    value = value.strip()
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
        return value
    match = re.fullmatch(r'([A-Za-z]+)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,)?\s+(\d{4})', value)
    if match is None:
        return None
    months = {'jan':'01','feb':'02','mar':'03','apr':'04','may':'05','jun':'06','jul':'07','aug':'08','sep':'09','oct':'10','nov':'11','dec':'12'}
    month = months.get(match.group(1).lower()[:3])
    if month is None:
        return None
    return match.group(3) + '-' + month + '-' + match.group(2).zfill(2)

def add_unique(rows, value):
    if value not in rows:
        rows.append(value)

def institution_mentions(text):
    result = []
    patterns = [r'\b(?:[A-Z][A-Za-z0-9&\'’\-]*\s+){1,6}(?:University|College|School)\b', r'\b(?:University|College|School)\s+of\s+[A-Z][A-Za-z0-9&\'’\-]*(?:\s+[A-Z][A-Za-z0-9&\'’\-]*){0,5}']
    for pattern in patterns:
        for match in re.finditer(pattern, text):
            item = {'name': match.group(0).strip(), 'start': match.start(), 'end': match.end()}
            duplicate = False
            for old in result:
                if old['start'] == item['start'] and old['end'] == item['end']:
                    duplicate = True
            if not duplicate:
                result.append(item)
    return result

def institution_names(mentions):
    result = []
    for item in mentions:
        add_unique(result, item['name'])
    return result

def covered(position, spans):
    for span in spans:
        if span[0] <= position and position < span[1]:
            return True
    return False

def clause_end(text, position):
    match = re.search(r'[.!?;]', text[position:])
    if match is None:
        return len(text)
    return position + match.start()

def event_time(text, position, limit, auxiliary):
    segment = text[position:limit]
    pattern = date_pattern()
    match = re.search(r'\bfrom\s+(' + pattern + r')\s+(?:to|through|until)\s+(' + pattern + r')', segment, re.I)
    if match is None:
        match = re.search(r'\bbetween\s+(' + pattern + r')\s+and\s+(' + pattern + r')', segment, re.I)
    if match is not None:
        bridge = segment[:match.start()]
        other = re.search(r'\band\s+[A-Z][A-Za-z\'’\-]*(?:\s+[A-Z][A-Za-z\'’\-]*){0,2}\s+(?:(?:was|were|is|are|has\s+been|have\s+been|had\s+been)\s+)?(?:enrolled|attend(?:ed|ing|s))\b', bridge)
        if other is not None:
            return None
        start = normalize_date(match.group(1))
        end = normalize_date(match.group(2))
        if start is not None and end is not None:
            return ['closed_interval', start, end, None]
        return None
    match = re.search(r'\bsince\s+(' + pattern + r')', segment, re.I)
    if match is not None:
        aux = re.sub(r'\s+', ' ', auxiliary.lower()).strip()
        if aux not in ('is', 'are', 'has been', 'have been'):
            return None
        start = normalize_date(match.group(1))
        if start is not None:
            return ['ongoing_since', start, None, None]
        return None
    match = re.search(r'\b(?:starting|beginning|commencing)(?:\s+on)?\s+(' + pattern + r')', segment, re.I)
    if match is not None:
        start = normalize_date(match.group(1))
        if start is not None:
            return ['onset_only', start, None, None]
        return None
    match = re.search(r'\bas\s+of\s+(' + pattern + r')', segment, re.I)
    if match is not None:
        date = normalize_date(match.group(1))
        if date is not None:
            return ['active_on_date', None, None, date]
    return None

def make_record(person, institution, timing, text):
    return {'person': person.strip(), 'institution': institution, 'form': timing[0], 'start_date': timing[1], 'end_date': timing[2], 'as_of_date': timing[3], 'witnesses': [{'field': 'facts', 'quote': text}]}

def apply(inputs, premises):
    text = inputs.get('facts')
    if type(text) is not str or len(text) == 0:
        return {'views': [{'extraction_status': 'unread', 'institutions': None, 'enrollments': None, 'attendance': None, 'witnesses': []}]}
    witness = [{'field': 'facts', 'quote': text}]
    mentions = institution_mentions(text)
    names = institution_names(mentions)
    institutions = []
    for name in names:
        institutions.append({'institution': name, 'witnesses': witness})
    enrollments = []
    attendance = []
    enrollment_spans = []
    attendance_spans = []
    person = r'([A-Z][A-Za-z\'’\-]*(?:\s+[A-Z][A-Za-z\'’\-]*){0,2})'
    auxiliary = r'(was|were|is|are|has\s+been|have\s+been|had\s+been)'
    for name in names:
        escaped = re.escape(name)
        enrollment_pattern = r'\b' + person + r'\s+' + auxiliary + r'\s+enrolled\s+(?:at|in)\s+' + escaped + r'\b'
        for match in re.finditer(enrollment_pattern, text):
            limit = clause_end(text, match.end())
            timing = event_time(text, match.end(), limit, match.group(2))
            if timing is None:
                continue
            add_unique(enrollments, make_record(match.group(1), name, timing, text))
            cue = re.search(r'\benrolled\b', match.group(0), re.I)
            if cue is not None:
                enrollment_spans.append((match.start() + cue.start(), match.start() + cue.end()))
            joint = re.search(r'\band\s+(?:(?:was|were|is|are|has\s+been|have\s+been|had\s+been)\s+)?attend(?:ed|ing|s)\s+(?:regular\s+)?classes\b', text[match.end():limit], re.I)
            if joint is not None:
                add_unique(attendance, make_record(match.group(1), name, timing, text))
                start = match.end() + joint.start()
                cue2 = re.search(r'attend(?:ed|ing|s)\s+(?:regular\s+)?classes', joint.group(0), re.I)
                if cue2 is not None:
                    attendance_spans.append((start + cue2.start(), start + cue2.end()))
        attendance_pattern = r'\b' + person + r'\s+' + auxiliary + r'\s+attend(?:ed|ing|s)\s+(?:regular\s+)?classes\s+(?:at|in)\s+' + escaped + r'\b'
        for match in re.finditer(attendance_pattern, text, re.I):
            limit = clause_end(text, match.end())
            timing = event_time(text, match.end(), limit, match.group(2))
            if timing is None:
                continue
            add_unique(attendance, make_record(match.group(1), name, timing, text))
            cue = re.search(r'attend(?:ed|ing|s)\s+(?:regular\s+)?classes', match.group(0), re.I)
            if cue is not None:
                attendance_spans.append((match.start() + cue.start(), match.start() + cue.end()))
    ambiguous = False
    institution_spans = []
    for item in mentions:
        institution_spans.append((item['start'], item['end']))
    for cue in re.finditer(r'\b(?:school|college|university)\b', text, re.I):
        if not covered(cue.start(), institution_spans):
            ambiguous = True
    for cue in re.finditer(r'\benroll(?:ed|ing|ment)?\b', text, re.I):
        if not covered(cue.start(), enrollment_spans):
            ambiguous = True
    attendance_cues = r'\b(?:attend(?:ed|ing|s)\s+(?:regular\s+)?classes|class\s+attendance|attendance\s+(?:at|in))\b'
    for cue in re.finditer(attendance_cues, text, re.I):
        if not covered(cue.start(), attendance_spans):
            ambiguous = True
    if ambiguous:
        return {'views': [{'extraction_status': 'unread', 'institutions': None, 'enrollments': None, 'attendance': None, 'witnesses': witness}]}
    return {'views': [{'extraction_status': 'complete', 'institutions': institutions, 'enrollments': enrollments, 'attendance': attendance, 'witnesses': witness}]}

