def date_pattern():
    return r'(?:January|February|March|April|May|June|July|August|September|October|November|December)\s+\d{1,2}(?:st|nd|rd|th)?(?:,)?\s+\d{4}|\d{4}-\d{2}-\d{2}'

def normalize_date(value):
    value = value.strip()
    if re.fullmatch(r'\d{4}-\d{2}-\d{2}', value):
        return value
    match = re.fullmatch(r'(January|February|March|April|May|June|July|August|September|October|November|December)\s+(\d{1,2})(?:st|nd|rd|th)?(?:,)?\s+(\d{4})', value)
    if match is None:
        return None
    months = {'January':'01','February':'02','March':'03','April':'04','May':'05','June':'06','July':'07','August':'08','September':'09','October':'10','November':'11','December':'12'}
    return match.group(3) + '-' + months[match.group(1)] + '-' + match.group(2).zfill(2)

def sentences(text):
    result = []
    for match in re.finditer(r'[^.!?]+[.!?]?', text):
        value = match.group(0).strip()
        if value:
            result.append(value)
    return result

def person_pattern():
    return r'([A-Z][A-Za-z\'’-]*(?:\s+[A-Z][A-Za-z\'’-]*){0,3})'

def named_institutions(sentence):
    result = []
    named = r'\b([A-Z][A-Za-z&.\'’-]*(?:\s+[A-Z][A-Za-z&.\'’-]*){0,7}\s+(?:University|College|School))\b'
    for match in re.finditer(named, sentence):
        value = match.group(1).strip()
        if value not in result:
            result.append(value)
    classified = r'\b([A-Z][A-Za-z&.\'’-]*(?:\s+[A-Z][A-Za-z&.\'’-]*){0,7})\s+(?:is|was)\s+(?:an?\s+)?(?:university|college|school)\b'
    for match in re.finditer(classified, sentence):
        value = match.group(1).strip()
        if value not in result:
            result.append(value)
    return result

def event_window(sentence, start):
    tail = sentence[start:]
    boundary = r'(?:;|,\s*and|\band)\s+' + person_pattern() + r'\s+(?:was|is|has|had|became|began|started|attended|enrolled)\b'
    match = re.search(boundary, tail[1:])
    if match is not None:
        return tail[:match.start() + 1]
    return tail

def time_record(window, channel):
    date = date_pattern()
    ranges = list(re.finditer(r'\bfrom\s+(' + date + r')\s+(?:to|through|until)\s+(' + date + r')', window))
    ranges += list(re.finditer(r'\bbetween\s+(' + date + r')\s+and\s+(' + date + r')', window))
    if len(ranges) == 1:
        start = normalize_date(ranges[0].group(1))
        end = normalize_date(ranges[0].group(2))
        if start is not None and end is not None:
            return {'form':'closed_interval','start_date':start,'end_date':end,'as_of_date':None}
    if len(ranges) > 1:
        return None
    since = list(re.finditer(r'\bsince\s+(' + date + r')', window))
    if len(since) == 1:
        start = normalize_date(since[0].group(1))
        if start is not None:
            return {'form':'ongoing_since','start_date':start,'end_date':None,'as_of_date':None}
    if len(since) > 1:
        return None
    as_of = list(re.finditer(r'\bas of\s+(' + date + r')', window))
    if len(as_of) == 1:
        value = normalize_date(as_of[0].group(1))
        if value is not None:
            return {'form':'active_on_date','start_date':None,'end_date':None,'as_of_date':value}
    if len(as_of) > 1:
        return None
    onset = list(re.finditer(r'\b(?:began|started|became)\b[^.;]*?\bon\s+(' + date + r')', window))
    if len(onset) == 1:
        value = normalize_date(onset[0].group(1))
        if value is not None:
            return {'form':'onset_only','start_date':value,'end_date':None,'as_of_date':None}
    if len(onset) > 1:
        return None
    if channel == 'attendance':
        active = list(re.finditer(r'\b(?:was|is)\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\b[^.;]*?\bon\s+(' + date + r')', window))
        if len(active) == 1:
            value = normalize_date(active[0].group(1))
            if value is not None:
                return {'form':'active_on_date','start_date':None,'end_date':None,'as_of_date':value}
    return None

def add_institution(rows, institution, quote):
    for row in rows:
        if row.get('institution') == institution:
            witness = {'field':'facts','quote':quote}
            if witness not in row['witnesses']:
                row['witnesses'].append(witness)
            return
    rows.append({'institution':institution,'witnesses':[{'field':'facts','quote':quote}]})

def make_event(person, institution, timing, quote):
    return {'person':person,'institution':institution,'form':timing['form'],'start_date':timing['start_date'],'end_date':timing['end_date'],'as_of_date':timing['as_of_date'],'witnesses':[{'field':'facts','quote':quote}]}

def channel_patterns(channel, institution):
    person = person_pattern()
    place = re.escape(institution)
    aux = r'(?:was|is|has been|had been)'
    if channel == 'enrollments':
        return [person + r'\s+(?:(?:was|is|has been|had been)\s+(?:currently\s+)?enrolled|became\s+enrolled)\s+(?:at|in)\s+' + place + r'\b', person + r'\s+' + aux + r'\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\s+(?:,?\s+)?and\s+(?:(?:was|is)\s+)?enrolled\s+(?:at|in)\s+' + place + r'\b']
    return [person + r'\s+' + aux + r'\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\s+(?:at|in)\s+' + place + r'\b', person + r'\s+' + aux + r'\s+(?:currently\s+)?enrolled\s+(?:at|in)\s+' + place + r'\b\s*(?:,?\s+and\s+)(?:(?:was|is)\s+)?(?:regularly\s+)?attending\s+(?:regular\s+)?classes\b', person + r'\s+' + aux + r'\s+(?:regularly\s+)?attending\s+(?:regular\s+)?classes\s*(?:,?\s+and\s+)(?:(?:was|is)\s+)?enrolled\s+(?:at|in)\s+' + place + r'\b']

def scan_channel(sentence, institutions, channel):
    records = []
    matched = False
    invalid = False
    for institution in institutions:
        for pattern in channel_patterns(channel, institution):
            for match in re.finditer(pattern, sentence):
                matched = True
                window = event_window(sentence, match.start())
                timing = time_record(window, 'attendance' if channel == 'attendance' else 'enrollment')
                if timing is None:
                    invalid = True
                else:
                    record = make_event(match.group(1), institution, timing, sentence)
                    if record not in records:
                        records.append(record)
    return {'records':records,'matched':matched,'invalid':invalid}

def apply(inputs, premises):
    facts = inputs.get('facts') if type(inputs) is dict else None
    if type(facts) is not str or not facts:
        return {'views':[{'extraction_status':'unread','institutions':None,'enrollments':None,'attendance':None,'witnesses':[]}]}
    parts = sentences(facts)
    institutions = []
    identities = []
    for sentence in parts:
        for institution in named_institutions(sentence):
            add_institution(institutions, institution, sentence)
            if institution not in identities:
                identities.append(institution)
    enrollments = []
    attendance = []
    ambiguous = False
    for sentence in parts:
        local_institutions = named_institutions(sentence)
        if re.search(r'\b(?:university|college|school)\b', sentence, re.IGNORECASE) and len(local_institutions) == 0:
            ambiguous = True
        enrollment_scan = scan_channel(sentence, identities, 'enrollments')
        attendance_scan = scan_channel(sentence, identities, 'attendance')
        for record in enrollment_scan['records']:
            if record not in enrollments:
                enrollments.append(record)
        for record in attendance_scan['records']:
            if record not in attendance:
                attendance.append(record)
        if re.search(r'\benroll(?:ed|ment|ing)?\b', sentence, re.IGNORECASE):
            if not enrollment_scan['matched'] or enrollment_scan['invalid']:
                ambiguous = True
        if re.search(r'\battend(?:ed|ing|ance)?\b[^.;]*\bclass(?:es)?\b|\bclass(?:es)?\s+attendance\b', sentence, re.IGNORECASE):
            if not attendance_scan['matched'] or attendance_scan['invalid']:
                ambiguous = True
        if re.search(r'\b(?:student|studied|studying|graduated|coursework|campus)\b', sentence, re.IGNORECASE):
            ambiguous = True
        if re.search(r'\bclass(?:es)?\b', sentence, re.IGNORECASE) and not re.search(r'\battend(?:ed|ing|ance)?\b[^.;]*\bclass(?:es)?\b', sentence, re.IGNORECASE):
            ambiguous = True
    witness = [{'field':'facts','quote':facts}]
    if ambiguous:
        return {'views':[{'extraction_status':'unread','institutions':None,'enrollments':None,'attendance':None,'witnesses':witness}]}
    return {'views':[{'extraction_status':'complete','institutions':institutions,'enrollments':enrollments,'attendance':attendance,'witnesses':witness}]}
